import os
import json

d = os.environ.get('RLM_SESSION_DIR', '')
session_file = os.path.join(d, '../../sessions', os.path.basename(d) + '.jsonl')

with open(session_file) as f:
    raw = f.read()

test_marker = 'Test input (30x30):'
m_test = raw.find(test_marker)
if m_test != -1:
    m_test += len(test_marker) + 2
    test_section = raw[m_test:]
    test_lines = test_section.replace('\\n', '\n').strip().split('\n')
    grid_lines = [l for l in test_lines if l.strip() and all(c.isdigit() or c.isspace() for c in l.strip())]
    test_input = [[int(x) for x in l.split()] for l in grid_lines[:30]]

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    regions = []
    for r1 in range(rows):
        for r2 in range(r1, rows):
            for c1 in range(cols):
                for c2 in range(c1, cols):
                    value = grid[r1][c1]
                    is_uniform = True
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            if grid[r][c] != value:
                                is_uniform = False
                                break
                        if not is_uniform:
                            break
                    if is_uniform:
                        regions.append((r1, r2, c1, c2, value))

    for (r1, r2, c1, c2, value) in regions:
        height = r2 - r1 + 1
        width = c2 - c1 + 1
        if value == 4 or height < 5 or width < 5:
            continue
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                result[r][c] = 4

    return result

output = transform(test_input)

# Save transform function and output
with open('/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out-reference-3/play/users/u019/system/state/workspace/programs/task-bbd6d89f.py', 'w') as f:
    f.write('''def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Find all rectangular regions of uniform values
    regions = []
    for r1 in range(rows):
        for r2 in range(r1, rows):
            for c1 in range(cols):
                for c2 in range(c1, cols):
                    value = grid[r1][c1]
                    is_uniform = True
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            if grid[r][c] != value:
                                is_uniform = False
                                break
                        if not is_uniform:
                            break
                    if is_uniform:
                        regions.append((r1, r2, c1, c2, value))

    # Replace uniform rectangular regions with 4s if at least 5x5
    for (r1, r2, c1, c2, value) in regions:
        height = r2 - r1 + 1
        width = c2 - c1 + 1
        if value == 4 or height < 5 or width < 5:
            continue
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                result[r][c] = 4

    return result
''')

# Submit
submit_json = json.dumps({"action": "submit", "grid": output})
